INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(149700, 0, 1497, 0, 0, 0, 'Undercity', 'Beneath the broken capital of Lordaeron lies the Undercity, seat of the Forsaken. The old kingdom kept its royal crypts, catacombs, dungeons and sewers here, under the palace of its kings, and the poorest of its people lived in the gloom below. The Scourge began carving these depths into a stronghold, but Arthas left the work unfinished when he was called north. When Sylvanas Windrunner broke free and turned on the dreadlords who ruled the ruins, her Forsaken claimed the warren and finished it as their own. Lifts descend from the ruined palace to the Trade Quarter at its heart, ringed by the Magic Quarter, the Rogues'' Quarter, the War Quarter and the Apothecarium, with foul canals running between them. Beyond lies the Royal Quarter, where the Dark Lady holds court.', 'warcraft.wiki.gg/wiki/Undercity (origins as royal crypts, catacombs, dungeons and sewers; poorest citizens lived there; Arthas left it unfinished; Forsaken completed it; quarter layout; elevators exit at Trade Quarter); quest 13257 reward text; npc_text 14931 and 15321 (Kor''kron Overseer gossip); creature 31419 (Sylvanas in Grommash Hold during the crisis phase); warcraft.wiki.gg/wiki/Battle_for_the_Undercity (coup, retaking)'),
(149701, 1, 1497, 1, 0, 0, 'The Elevators', 'Three great lifts join the ruined palace of Lordaeron to the Trade Quarter far below, the main road between the open ruins and the city of the dead. They rise and fall without pause through long, dark shafts, and their doors close so quickly that the careless learn to step lively. Every traveler bound for the city''s quarters, from the ruins above or the zeppelins beyond the walls, passes through them.', 'AreaTable 4617 Elevator (parent 1497); WMOAreaTable rows 28864, 28882, 28865 map three Undercity WMO groups to area 4617; warcraft.wiki.gg/wiki/Undercity (elevators connect the upper city to the depths; Trade Quarter at their lower exits; doors close dangerously fast); creature_text 32518 groups 15-17 (elevator destroyed, cyclones lower us to safety); creature_text 32365 group 1 (shaft is trapped); DB transports: Undervators 20649, 20652, 20655 (continuous); tirisfal.json 8516 (zeppelins outside the walls)'),
(149702, 2, 1497, 1, 2, 0, 'Lady Sylvanas Windrunner', 'Once Ranger-General of Silvermoon, Sylvanas Windrunner fell defending Quel''Thalas from Arthas and was raised as a banshee in his service. When the Lich King''s grip faltered she broke free, turned on the dreadlords who held Lordaeron and named her freed undead the Forsaken. She rules them from the Royal Quarter, curt with visitors, for the city does not run itself. She sends her chosen to Nathanos Blightcaller, one of her first champions, and few in her ranks serve her with more devotion.', 'warcraft.wiki.gg/wiki/Sylvanas_Windrunner (Ranger-General, raised by Arthas, broke free, dreadlords, blood elves, Battle for the Undercity); npc_text 10212 (Sylvanas gossip); quest 5961 description (Nathanos among the first of my champions); npc_text 10212 (city does not run itself)'),
(149703, 2, 1497, 2, 2, 0, 'Varimathras', 'Varimathras was one of three dreadlord brothers who ruled Lordaeron''s undead for the Burning Legion after Arthas went north. When Sylvanas broke his forces he begged for his life and offered his service, and for years he stood at her side in the Royal Quarter as her lieutenant, with the Deathstalkers first serving as his elite guard. His loyalty was a mask. After the Wrathgate he and Putress seized the Undercity, turning its halls into a fortress of demons and blight against the Horde.', 'warcraft.wiki.gg/wiki/Varimathras (brothers Balnazzar and Detheroc, begged Sylvanas for his life, lieutenant, coup, unseen Master); warcraft.wiki.gg/wiki/Deathstalker (began as Varimathras''s elite guard); creature_text 31565 (Varimathras battle lines: years wasted, a thousand-thousand pardons, Master); quest 13266 reward text (demons and blight); quest 13267 description; zone_undercity.cpp: Varimathras entry 31565 summoned in the Horde battle; warcraft.wiki.gg/wiki/Varimathras (defeated by Sylvanas herself; unseen Master rebukes him); zone_undercity.cpp: Varimathras made attackable after SAY_VALIMATHRAS_ATTACK, killable by players for credit'),
(149704, 2, 1497, 3, 0, 0, 'Grand Apothecary Putress', 'Grand Apothecary Putress rose to the head of the Royal Apothecary Society after winning Sylvanas''s favor with a vow to take the plague that made the Forsaken and make it their own weapon. From the Apothecarium his chemists refined the New Plague, a blight lethal to living and undead alike. At the Wrathgate in Northrend he turned it on Alliance, Horde and Scourge together, striking down Highlord Bolvar Fordragon and many soldiers of both sides. Then he went to ground in the depths of the Undercity, which traitors among the Forsaken had seized.', 'warcraft.wiki.gg/wiki/Royal_Apothecary_Society (Putress founder, New Plague lethal to living and undead, Wrathgate, killed by Varian''s forces); warcraft.wiki.gg/wiki/Battle_for_the_Undercity (Bolvar and thousands of soldiers killed); quest 13257 reward text (Putress discovered the cure for the recent Scourge plague outbreak); creature_text 31530 groups 5-6 (I will consume more energy, I see everything); zone_undercity.cpp: Putress 31530 summoned and fought in the Alliance battle; zone_undercity.cpp (Putress spawned at the Apothecarium position, blight generators empower him; world state APOTHECARIUM_FIGHT_A)'),
(149705, 2, 1497, 4, 2, 0, 'Master Apothecary Faranell', 'Master Apothecary Faranell directs the work of the Royal Apothecary Society in the Apothecarium, overseeing its most ambitious and most ghoulish projects: guano from the bats of Razorfen Kraul, hearts cut from Scarlet zealots, venoms and composites sent home by his apothecaries in the field. He speaks of it all with unsettling delight, for every grisly reagent brings the Forsaken closer to the new plague the Dark Lady awaits.', 'quests 1109 and 1113 (guano, hearts of Scarlet zealots); quests 513, 515 and 2938 reward text; npc_text 14940 (Faranell gossip: Putress an unfortunate anomaly); creature_text 2055 (make up for the tragic misguidance, continue our research in peace); warcraft.wiki.gg/wiki/Royal_Apothecary_Society (Faranell leads the Society); tirisfal.json 8530 (Sylvanas''s challenge to the Society: a new plague); quest 513 reward text (the Dark Lady impressed by progress toward the new plague)'),
(149706, 2, 1497, 5, 2, 13, 'Bragor Bloodfist', 'Bragor Bloodfist is a Kor''kron captain whom Thrall has sent to stand at the Dark Lady''s side in the Royal Quarter. With most of the Forsaken army committed to Vengeance Landing in Northrend, the Warchief''s guard now reinforces the Undercity, and Bragor sends agents against the Scarlet Crusade, receives word from the Hillsbrad front, and hunts a Scourge emissary named Malcin near Razorfen Downs. A living orc among the dead, he keeps dangerous books from the Forsaken as carefully as from the Shadow Council. He judges newcomers by their deeds, and already counts the human king among the threats the Horde must one day end.', 'warcraft.wiki.gg/wiki/Bragor_Bloodfist (Kor''kron captain, replaced Varimathras in 3.3.0, sent by Thrall); npc_text 15321 (forces deployed to Vengeance Landing); quests 6144, 14351, 14352, 14353, 14355, 14356; npc_text 15319 (Bragor gossip on Varimathras); quest 14351 reward text (with that king leading them, the humans remain a problem); quest 14356 (books kept from the Searing Blade and the Forsaken alike)'),
(149707, 2, 1497, 6, 2, 13, 'Overseer Kraggosh', 'Overseer Kraggosh is the Kor''kron orc posted inside the Apothecarium itself, and he makes no secret of how little he likes it. Since Putress loosed his blight at the Wrathgate, the Warchief has trusted the Royal Apothecary Society about as far as he could throw it, and Kraggosh is the result: no abomination guards, no secrecy, no plotting in the dark. The apothecaries can do nothing without him, and he has warned Master Apothecary Faranell that if the Society so much as spits without leave, the place will be shut down by force. His fellow overseers stand watch across the city and treat the Forsaken with open contempt.', 'npc_text 14934 (Kraggosh gossip); creature_text 36217 (I''ve got my eye on you, Faranell; no abominations, no secrecy; spit without my permission); npc_text 14931 and 14933 (Kor''kron Overseer gossip: the forsaken need watching, bonebag); warcraft.wiki.gg/wiki/Royal_Apothecary_Society (Kraggosh warns the apothecaries)'),
(149708, 2, 1497, 7, 2, 0, 'Sharlindra', 'Sharlindra is a banshee of the Dark Lady''s court and long in her service. She was present when Varimathras offered Sylvanas a place in his new order, and privately wondered whether accepting might have been the wiser course. She fought beside the Forsaken when they stormed the stronghold of the dreadlord Detheroc. Today she keeps to the Royal Quarter and directs agents abroad through lieutenants such as Melisara at Tarren Mill. When the ogre Mug''Thol stole the Crown of Will meant for Sylvanas, and the Dark Lady wanted an example made, it was Sharlindra who set the task in motion.', 'warcraft.wiki.gg/wiki/Sharlindra (banshee, Royal Quarter, witnessed Varimathras''s offer, attack on Detheroc''s stronghold, lieutenant Melisara); quests 495 and 521'),
(149709, 2, 1497, 8, 2, 0, 'Parqual Fintallas', 'Before the plague took him, Parqual Fintallas was a great historian of Lordaeron''s human kingdom. Death has not cured him of scholarship. He lingers in the Undercity still seeking enlightenment, though of a different kind, and holds that knowledge of the world will outlast mere strength. To those who would prove their minds he sets a final test of lore, sending them first to the Scarlet Monastery for a book its zealots once used to train paladins against his kind. His question, fittingly, concerns the very creature that became the Lich King and spread the plague across Lordaeron.', 'quest 1159 description (great historian for the humans before the Plague); quest 1160 description (Beginnings of the Undead Threat, used to train paladins against my kind; knowledge more important than strength); npc_text 5822 (his question); quest 6628'),
(149710, 2, 1497, 9, 2, 0, 'Apothecary Zinge', 'Apothecary Zinge of the Royal Apothecary Society has a sharp eye for opportunity, especially other people''s. By her account Apothecary Keever, at work in the next room, is touched in the head, yet his research might bear fruit if pursued by a clever researcher, and Zinge means to be that researcher. She sends her errand runners to Alessandro Luca of Blue Moon Odds and Ends, who pines for her company, and on to the Tanaris desert to test the flesh of basilisks, scorpids and hyenas. She rewards those who stay useful, and corresponds with colleagues as far afield as the Crossroads and Kargath.', 'quests 232 and 238 (Keever is touched, Luca''s kit and his longing for Zinge''s presence); quest 243 (Tanaris samples); quest 864 reward text (Keever''s insanity my genius; reward those who remain useful); quests 1358 (Helbrim at the Crossroads) and 4133 (Vivian Lagrave at Kargath)'),
(149711, 3, 1497, 1, 0, 0, 'The Battle for the Undercity', 'At the Wrathgate in Northrend, Grand Apothecary Putress turned his blight on Alliance, Horde and Scourge alike, and Highlord Bolvar Fordragon fell with many soldiers of both sides. The treachery did not end there. Traitors within the Forsaken rose and seized the Undercity, and the Horde lost the capital of its ally, while Putress himself hid somewhere in its depths. Thrall has sworn that the perpetrators of this unforgivable crime will be brought to justice, and prepares to lay siege to the fallen city. Those who fought side by side at the Wrathgate are each left to count their dead.', 'quest 13257 reward text (executed or banished, refugees, martial law); quest 13266 description and reward text; quest 13267 description and reward text (gone are the days of Alliance and Horde battling alongside each other); quests 13371 and 13377 descriptions; creature_text 32518, 32365, 32401, 32402; warcraft.wiki.gg/wiki/Battle_for_the_Undercity (Varian, Jaina, Broll, Valeera in the sewers; Jaina froze the combatants and teleported the Alliance out); creature 31419 (Sylvanas spawned in Grommash Hold during the crisis); zone_undercity.cpp (Horde: courtyard, elevator destroyed, cyclones, Royal Quarter; Alliance: sewers, Putress at the Apothecarium, throne room, Deep Freeze and Greater Mass Teleport)'),
(149712, 3, 1497, 2, 2, 0, 'The Lady''s Necklace', 'Windrunner Spire, on the coast of the Ghostlands, was once the home of the Windrunner family, and of Sylvanas, the Ranger-General who fell defending Quel''Thalas and now rules the Forsaken. Today mindless Scourge haunt its halls. Among them a necklace has turned up, a remarkable piece that shimmers as though the gloom of the Ghostlands cannot touch it. Its inscription names it the lost property of Lady Sylvanas Windrunner herself, and whoever recovers it does best to take it first to High Executor Mavren at Tranquillien, the highest ranking Forsaken in the land, who will know what to do with it.', 'quest 9175 description and reward text (Windrunner Spire, inscription, Mavren at Tranquillien); quest 9180 description, completion and reward text; creature_text 10181 groups 0-2 (kneels, Belore, Highborne spirits sing about the Sin''dorei); warcraft.wiki.gg/wiki/Sylvanas_Windrunner (Alleria''s necklace, lament); ghostlands.json 343316 Windrunner Spire (quest 9173: original home of Sylvanas, overrun by Scourge)'),
(149713, 3, 1497, 3, 2, 0, 'The Crown of Will', 'Lady Sylvanas desired the Crown of Will, a relic to be had in Alterac, and sent the ogre Mug''Thol and his warband to fetch it, bound to her service by possession. Mug''Thol found the crown and, being an ogre, could not resist putting it on. Its power let him throw off the Dark Lady''s will. She wants an example made, and Sharlindra of the Royal Quarter passes the task to her lieutenant Melisara at Tarren Mill, who means to deal with the ogre quickly, thoroughly and without incident. First the Crushridge, who have overrun the ruins of Alterac under Mug''Thol, must be thinned.', 'quests 495, 518, 519, 520 and 521 (descriptions and reward text)'),
(149714, 3, 1497, 4, 2, 0, 'The Deathstalkers', 'Promising rogues of the Horde may find themselves summoned to the Rogues'' Quarter by Mennet Carkad, and few ignore the summons, for none care to learn what became of the last who did. Carkad tests candidates for the Deathstalkers, the Dark Lady''s elite guard, and he does not pretend the test is safe: it could mean death. He tells the recruit little. First they must obtain the personal effects of Astor Hadren, a messenger who travels between Silverpine and the Undercity, by whatever means suits them. The less the recruit knows of the business the better, Carkad says, but success will earn the rest.', 'quests 1885, 14420, 14419, 14421 and 14418 (descriptions, log text and reward text); warcraft.wiki.gg/wiki/Deathstalker (elite assassins and spies; spying on Andron Gant); creature 36517 Aleric Hawkins (The Deathstalkers) spawned beside Sylvanas'),
(149715, 3, 1497, 5, 2, 0, 'Seeping Corruption', 'In the Apothecarium, Chemist Cuely keeps a patient who did not come to be studied. Thersa Windsong, a tauren, was wounded by naga in the Ruins of Eldarath in Azshara and afterward drank from a tide pool on the beach. She has been sick ever since. No priest or shaman could help her, and she came to the Undercity because its alchemists were said to be studying long and hard on a cure for their own affliction, though the place makes her feel far from welcome. Cuely wants to know what she drank, and has a helper fill labeled vials at the pools.', 'quests 3568, 3569 and 3570 (descriptions and reward text); creature_text 8393 and 8390; warcraft.wiki.gg/wiki/Thersa_Windsong (tauren; turns green and dies after drinking the elixir)'),
(149716, 3, 1497, 6, 2, 0, 'The Jeremiah Blues', 'Among the records the Forsaken keep, few are stranger than the city census. Royal Overseer Bauhaus tends it by arcane means and disciplined mind, tracking the populace since the city was freed from the Scourge, and he is asked often enough whether someone is dead. When a dusty parcel turned up in the Plaguelands, addressed more than four years earlier to one Jeremiah Felstone of Lordaeron, the census was the place to learn whether its recipient had outlived the plague, and what he had become.', 'quest 5023 description and reward text; quest 5049 description, log text and reward text; quest 5050 description; npc_text 3653 (Bauhaus census gossip)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(149700, 1, 0, 12, 'At her side stands the dreadlord Varimathras, one of three demon brothers who ruled Lordaeron''s undead for the Burning Legion. When the Forsaken broke his forces he begged for his life and swore himself to her service, and he has served as her lieutenant ever since. The Deathstalkers, her elite agents, first served as his guard.', 'warcraft.wiki.gg/wiki/Varimathras (brothers Balnazzar and Detheroc, begged Sylvanas for his life, her lieutenant until the Battle for the Undercity, patch 3.0); warcraft.wiki.gg/wiki/Deathstalker (began as Varimathras''s elite guard)'),
(149700, 2, 13, 255, 'The war in Northrend brought treachery home. After Grand Apothecary Putress loosed his blight on Alliance and Horde alike at the Wrathgate, traitors within the city rose and seized it, and the Horde lost the capital of the Forsaken. Somewhere in its depths, Putress went to ground.', 'quest 13257 reward text (the Horde has lost the Undercity); quest 13370 description and reward text (Putress at the Wrath Gate; they have lost the Undercity); creature_text 32363 (a betrayal from within; the Horde has lost the Undercity); quest 13377 description (deep inside the Undercity hides the assassin)'),
(149700, 3, 13, 255, 'The city has been won back. Thrall and the Dark Lady fought their way down through blight and demons to the Royal Quarter, broke the traitors'' last stand there, and Sylvanas took back the seat of her power.', 'zone_undercity.cpp (Horde: courtyard, inner sanctum, Royal Quarter; Alliance: Thrall and Sylvanas met in the throne room); creature_text 32518 group 28 (the Royal Quarter belongs to you); creature_text 32401 group 22 (THRALL! HERE?)'),
(149700, 4, 13, 255, 'Orcs of the Kor''kron, the Warchief''s own guard, now walk the Undercity''s halls. Thrall sent them to reinforce the city while the bulk of its forces fight at Vengeance Landing in Northrend, and to keep watch on the Forsaken: had anyone watched them more closely from the start, the overseers say, the Wrathgate might never have happened.', 'npc_text 14931, 14933 and 15321 (Kor''kron Overseer 36213 gossip, menu 10769: the forsaken need watching; Wrath Gate; bulk of forces at Vengeance Landing); DB: 45 Kor''kron Overseer spawns in the city'),
(149701, 1, 13, 255, 'When the Horde came to retake the city, the way down was closed to it. The rebels had wrecked the lift and trapped the shaft, and Sylvanas warned that a fall would mean certain death. Thrall answered by calling on the spirits of air, and cyclones lowered the Horde''s champions safely into the inner sanctum below, where Khanok the Impassable barred their way.', 'creature_text 32518 groups 15-18 (elevator destroyed, cyclones lower us to safety, inner sanctum breached); creature_text 32365 group 1 (shaft is trapped); zone_undercity.cpp (Khanok the Impassable 32511 summoned in the inner sanctum after the cyclone descent; killable, his death opens the way on)'),
(149702, 1, 8, 255, 'In recent years she has championed the blood elves of Quel''Thalas, once her own people, and stood for their entry into the Horde while others doubted them. Their envoys come before her throne in the Royal Quarter.', 'quests 9621 and 9812 descriptions (doubts among our potential new allies; she is already on our side) and reward text; warcraft.wiki.gg/wiki/Sylvanas_Windrunner (blood elves)'),
(149702, 2, 0, 12, 'The dreadlord Varimathras serves at her side as her lieutenant, the demon who begged for his life when her Forsaken broke his rule and swore himself to her. She keeps him close.', 'warcraft.wiki.gg/wiki/Varimathras (lieutenant until patch 3.0)'),
(149702, 3, 13, 255, 'After the Wrathgate her own court turned on her. The dreadlord Varimathras, her lieutenant of many years, and Grand Apothecary Putress seized the Undercity in a bloody coup. The Dark Lady was nearly killed, and fled to Orgrimmar to wait in the Warchief''s hold while the Horde prepared to take her city back.', 'quest 13257 reward text (Sylvanas was nearly killed in the coup); creature 31419 (Sylvanas in Grommash Hold during the crisis)'),
(149702, 4, 13, 255, 'She came home at Thrall''s side, promising the traitors an agonizing death. Together they fought down through the fallen city, and when Varimathras fell in the throne room she named it the fate of all enemies of the Horde. Thrall gave the Royal Quarter back to her, a right, he said, she had won with her own blood.', 'creature_text 32365 groups 3 and 7 (agonizing death; such will be the fate of all enemies of the Horde); creature_text 32518 group 28 (the Royal Quarter belongs to you)'),
(149703, 1, 13, 255, 'The Horde came for him through the fallen city, and he taunted it from the start: it would have its city back only in pieces. In the throne room, cornered by Thrall and Sylvanas, he opened portals for his demon kin, raged that years of tireless planning would not end like this, and begged a thousand-thousand pardons of an unseen Master, swearing to deal with the intruders himself. He could not. He fell with a last gasp: years, wasted.', 'creature_text 31565 groups 2, 7, 12 and 13; zone_undercity.cpp (Varimathras 31565 and his portals 31811 in the Royal Quarter); warcraft.wiki.gg/wiki/Varimathras (unseen Master)'),
(149704, 1, 13, 255, 'To the Horde the betrayal cut deeper. Putress was the same apothecary credited with discovering the cure for the recent outbreak of the Scourge''s plague, and he had not acted alone: with the dreadlord Varimathras he took the Undercity in a bloody coup, and those who would not side with them were executed or banished.', 'quest 13257 reward text'),
(149704, 2, 13, 255, 'King Varian''s forces broke into his laboratory in the Apothecarium, where blight generators fed him power. Cornered, Putress swore it would not end like this after so many years of work, swallowed ever more energy and raved that he saw everything. It availed him nothing. He died there, and Varian declared justice served.', 'creature_text 31530 groups 5-6; creature_text 32401 group 16 (and justice is served); zone_undercity.cpp (blight generators 36212 cast Blight Empowerment on Putress; Putress made attackable)'),
(149705, 1, 13, 255, 'Since Putress''s betrayal the Society labors under the eye of the Warchief''s Kor''kron, and Faranell has turned diplomat. He assures his overseer that the apothecaries wish only to make amends for the tragic misguidance that ended so many lives, and to continue their research in peace. Putress, he insists, was an unfortunate anomaly.', 'npc_text 14940 (Faranell gossip: Putress an unfortunate anomaly); creature_text 2055 (tragic misguidance which ended so many lives; research in peace)'),
(149706, 1, 13, 255, 'He came after the city was retaken. The fall of Varimathras left an empty place at the Dark Lady''s side, and the Warchief filled it with one of his own: many duties the dreadlord once held, from the war on the Scarlet Crusade to the reports from Hillsbrad, now pass through Bragor''s hands.', 'warcraft.wiki.gg/wiki/Bragor_Bloodfist (replaced Varimathras in 3.3.0, sent by Thrall); quests 14351 and 14355 (Hillsbrad, Scarlet Monastery)'),
(149711, 1, 13, 255, 'Thrall named the traitors: Putress, and with him the dreadlord Varimathras, the Dark Lady''s own lieutenant. Those who would not side with their regime were executed or banished, Sylvanas herself was nearly killed, and the Forsaken who escaped fled to Orgrimmar to wait for the crisis to be resolved.', 'quest 13257 reward text'),
(149711, 2, 13, 255, 'The Horde struck from the ruins with Thrall and Sylvanas at its head. It fought through the courtyard against the traitors'' blight, found the lift wrecked and the shaft trapped, and dropped into the inner sanctum on cyclones the Warchief called. Beyond lay the Royal Quarter, where Varimathras opened portals for his demon kin and fell before Thrall and the Dark Lady.', 'quest 13266 and 13267 descriptions; creature_text 32518, 32365, 31565; zone_undercity.cpp (Horde: courtyard, elevator destroyed, cyclones, inner sanctum, Royal Quarter)'),
(149711, 3, 13, 255, 'The Alliance came for Putress through the sewers. From the sewer entrance, where Broll Bearmantle and Valeera Sanguinar kept watch, King Varian and Jaina Proudmoore led their soldiers down past the engorged blight worm that guarded the tunnels to the Apothecarium. There, among his blight generators, Putress met his end, and Varian declared justice served.', 'quests 13371 and 13377 descriptions; creature_text 32401 groups 6-17; zone_undercity.cpp (Alliance: sewers, Engorged Blight Worm 32483, Putress at the Apothecarium); warcraft.wiki.gg/wiki/Battle_for_the_Undercity (Varian, Jaina, Broll, Valeera in the sewers)'),
(149711, 4, 13, 255, 'The day ended in the throne room, with the Horde holding it. Varian marched in declaring that Putress was only the first strike, and that the time had come to disband the Horde''s treacherous kingdom of murderers and thieves. Then he turned his blades on Thrall. Jaina begged him to stop, froze the combatants where they stood and carried the Alliance away. It did not have to be like this, she said. The fellowship of the Wrathgate did not survive the day.', 'creature_text 32401 groups 26-30; creature_text 32402 groups 3-4; creature_text 32518 group 30 (Alliance horns); zone_undercity.cpp (both versions: Wrynn''s throne room speech, Deep Freeze 61224, Greater Mass Teleport 60516); quest 13267 reward text (gone are the days of Alliance and Horde battling alongside each other)'),
(149712, 1, 0, 255, 'Mavren knew the necklace for what it was: a gift to Lady Sylvanas from her sister, Alleria. It had to go to her at once, to the Royal Quarter where she holds court, by way of the orb of translocation in Silvermoon City that crosses to the Undercity.', 'quest 9180 description'),
(149712, 2, 0, 255, 'Sylvanas seized it, startled into memory, then mastered herself and scorned the gift. Alleria, she declared, was a long dead memory, and the trinket meant nothing to the queen of the Forsaken. She let it fall and dismissed the bearer. Yet a moment later she knelt and took it up again. Whispering ''Belore'', she wove a glamour that called forth Highborne spirits, and the chamber filled with their ancient song of the sin''dorei.', 'quest 9180 completion and reward text; creature_text 10181 groups 0-2'),
(149713, 1, 0, 255, 'The snow of Alterac bloomed red with ogre blood before Melisara was satisfied, and then she wanted heads: those of Targ, Muckrake and Glommus, Mug''Thol''s loyal lieutenants. When they were brought to her she promised that his would join them, all four mounted on pikes above Alterac as a monument to those who defy the Dark Lady.', 'quests 518 and 519 description and reward text'),
(149713, 2, 0, 255, 'Mug''Thol fell at last, and his head and the crown came back to Tarren Mill. His head would adorn the highest peak of the ruins of Alterac, Melisara declared, and the Deathguard would sweep what remained of the Crushridge into the ground.', 'quest 520 description and reward text'),
(149713, 3, 0, 255, 'The crown itself went back to Sharlindra, to be laid before the queen it was always meant for. She marveled that something so simple could hold such power and fall into such clumsy hands, and promised that Lady Sylvanas would hear who had brought it home.', 'quest 521 description and reward text'),
(149714, 1, 0, 255, 'Astor''s letter of introduction is the key. Carkad''s leaders suspect Andron Gant, a merchant whose shop stands by the Apothecarium, of aiding some other power, and they want proof of whom he serves. The recruit is to call on him posing as the messenger he expects. Andron, Carkad judges, lacks the wit to be suspicious.', 'quest 14419 description; quest 14420 reward text'),
(149714, 2, 0, 255, 'Andron suspected nothing. He welcomed the false messenger, handed over his ledger with his regards and asked that the same courier be sent again. The ledger named his true buyers: the Syndicate. The lords of Alterac, Carkad mused, have fallen far since their betrayal, and with that he welcomed the recruit into the Deathstalkers.', 'quest 14419 reward text; quest 14421 description; quest 14418 description'),
(149714, 3, 0, 255, 'The new agent carried the ledger to Aleric Hawkins, master of the Deathstalkers, in the Royal Quarter. Hawkins found the work admirable, commended the recruit''s part in it and hoped such service would become routine, for his Deathstalkers always have use for a capable agent.', 'quest 14418 log text and reward text; creature 36517 Aleric Hawkins (The Deathstalkers) beside Sylvanas'),
(149715, 1, 0, 255, 'Cuely is pleased the samples came back before she died. He has studied her symptoms with interest, and he is frank about where this leads: she cannot survive, so she might as well die doing something noble for the Forsaken. He brews an elixir from the samples and has it carried to her. Perhaps it will cure her, he says, perhaps not.', 'quest 3568 completion and reward text; quest 3569 description'),
(149715, 2, 0, 255, 'Thersa finds Cuely disturbingly accommodating, but if he says the elixir will help her, she has no other choice and no time left to find another remedy. She drinks, praying that the Earthmother will watch over her spirit.', 'quest 3569 reward text; creature_text 8393; warcraft.wiki.gg/wiki/Thersa_Windsong (turns green and dies after drinking the elixir)'),
(149715, 3, 0, 255, 'The elixir took hold faster than even Cuely had dreamed, and Thersa did not survive it. Pleased, the chemist turns at once to the remaining samples, certain they will soon be of use to Lady Sylvanas and the Forsaken.', 'quest 3570 reward text (auto-complete quest, so QUEST_DONE); creature_text 8390'),
(149716, 1, 0, 255, 'The census held the answer. Like some Forsaken, Felstone had shed his old name with his old life, and now sold cockroaches as Jeremiah Payson, groveling under a walkway near the bank. Bauhaus wished the bearer well on so world-shaping an errand.', 'quest 5023 reward text; quest 5049 description'),
(149716, 2, 0, 255, 'Jeremiah took the visit badly. He had not used the name Felstone in years, and the sender, his sister Janice, had been dead for four. He called the bearer a vulture and threatened to break his own brittle foot on them, until he saw the parcel truly came from her.', 'quest 5049 reward text'),
(149716, 3, 0, 255, 'Inside lay her personal effects: the deed to the Felstone farm, which he chose not to reclaim, and half of a good luck charm, the other half her husband''s. If her spirit still walked the farm unable to rest, he asked, would the bearer return the charm to her, so that knowing he had these things might let her be at peace.', 'quest 5050 description');
